'use strict';

// MODULES //

var isLayout = require( '@stdlib/blas/base/assert/is-layout' );
var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var max = require( '@stdlib/math/base/special/fast/max' );
var resolveOrder = require( '@stdlib/blas/base/layout-resolve-enum' );
var resolvePenaltyStr = require( '@stdlib/ml/base/sgd/penalty-resolve-str' );
var resolveLRStr = require( '@stdlib/ml/base/sgd/learning-rate-resolve-str' );
var resolveLossFnStr = require( '@stdlib/ml/base/sgd/loss-function-resolve-str' );
var format = require( '@stdlib/string/format' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Trains a linear model via stochastic gradient descent.
*
* @private
* @param {string} order - storage layout
* @param {NonNegativeInteger} M - number of samples
* @param {NonNegativeInteger} N - number of features
* @param {Float64Array} X - input matrix
* @param {NonNegativeInteger} LDX - stride of the first dimension of `X` (a.k.a., leading dimension of the matrix `X`)
* @param {Float64Array} y - target array
* @param {integer} strideY - stride length for `y`
* @param {Float64Array} w - weight array
* @param {integer} strideW - stride length for `w`
* @param {Float64Array} workspace - workspace array
* @param {integer} strideWS - stride length for `workspace`
* @param {Params} params - parameters object
* @throws {TypeError} first argument must be a valid order
* @throws {TypeError} thirteenth argument's `penalty` member must be a valid penalty
* @throws {TypeError} thirteenth argument's `learningRate` member must be a valid learning rate
* @throws {TypeError} thirteenth argument's `lossFunction` member must be a valid loss function
* @throws {RangeError} second argument must be a nonnegative integer
* @throws {RangeError} third argument must be a nonnegative integer
* @throws {RangeError} sixth argument must be non-zero
* @throws {RangeError} fifth argument must be a valid stride
* @throws {RangeError} eighth argument must be a valid stride
* @throws {RangeError} tenth argument must be a valid stride
* @throws {RangeError} twelfth argument must be a valid stride
* @returns {Float64Array} `w`
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Params = require( '@stdlib/ml/base/sgd/params/float64' );
* var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
*
* var M = 50;
* var N = 5;
* var lambda = 2.5;
* var eta0 = 0.01;
*
* var params = new Params({
*    'penaltyParams': new Float64Array( [ lambda, 0.0 ] ),
*    'learningRateParams': new Float64Array( [ eta0, 0.0 ] ),
*    'intercept': 0.0,
*    'maxIter': 500,
*    'penalty': 'l2',
*    'learningRate': 'constant',
*    'lossFunction': 'hinge',
*    'fitIntercept': true
* });
*
* var y = discreteUniform( M, 0.0, 30.0 );
* var X = discreteUniform( M*N, -5.0, 5.0 );
* var w = discreteUniform( N, -0.05, 0.05 );
* var workspace = new Float64Array( N );
*
* var out = dsgdTrainer( 'row-major', M, N, X, N, y, 1, w, 1, workspace, 1, params );
* returns <Float64Array>
*/
function dsgdTrainer( order, M, N, X, LDX, y, strideY, w, strideW, workspace, strideWS, params ) { // eslint-disable-line max-params, max-len
	var iscm;
	var lsfn;
	var vala;
	var lr;
	var p;

	if ( !isLayout( order ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a valid order. Value: `%s`.', order ) );
	}
	p = resolvePenaltyStr( params.penalty );
	lr = resolveLRStr( params.learningRate );
	lsfn = resolveLossFnStr( params.lossFunction );
	if ( p === null ) {
		throw new TypeError( format( 'invalid argument. Thirteenth argument\'s `penalty` member must be a valid penalty. Value: `%s`.', params.penalty ) );
	}
	if ( lr === null ) {
		throw new TypeError( format( 'invalid argument. Thirteenth argument\'s `learningRate` member must be a valid learning rate. Value: `%s`.', params.learningRate ) );
	}
	if ( lsfn === null ) {
		throw new TypeError( format( 'invalid argument. Thirteenth argument\'s `lossFunction` member must be a valid loss function. Value: `%s`.', params.lossFunction ) );
	}
	if ( M < 0 ) {
		throw new RangeError( format( 'invalid argument. Second argument must be a nonnegative integer. Value: `%d`.', M ) );
	}
	if ( N < 0 ) {
		throw new RangeError( format( 'invalid argument. Third argument must be a nonnegative integer. Value: `%d`.', N ) );
	}
	iscm = isColumnMajor( order );
	if ( iscm ) {
		vala = M;
	} else {
		vala = N;
	}
	if ( LDX < max( 1, vala ) ) {
		throw new RangeError( format( 'invalid argument. Sixth argument must be greater than or equal to max(1,%d). Value: `%d`.', vala, LDX ) );
	}
	if ( strideY === 0 ) {
		throw new RangeError( format( 'invalid argument. Eighth argument must be non-zero. Value: `%d`.', strideY ) );
	}
	if ( strideW === 0 ) {
		throw new RangeError( format( 'invalid argument. Tenth argument must be non-zero. Value: `%d`.', strideW ) );
	}
	if ( strideWS === 0 ) {
		throw new RangeError( format( 'invalid argument. Twelfth argument must be non-zero. Value: `%d`.', strideY ) );
	}
	// Check if we can early return...
	if ( M === 0 || N === 0 ) {
		return w;
	}
	return addon( resolveOrder( order ), M, N, X, LDX, y, strideY, w, strideW, workspace, strideWS, params ); // eslint-disable-line max-len
}


// EXPORTS //

module.exports = dsgdTrainer;
